exercises.solution:
#include <stdio.h>

static int g_sum = 0;

static int adder(int x) {
    g_sum += x;
    return g_sum;
}

int main(void) {
    printf("%d\n", adder(5));
    printf("%d\n", adder(10));
    return 0;
}
